public static function get_role_hash( \WP_User $user ): string {
	if ( empty( $user->roles ) ) {
		return '';
	}
	$roles = $user->roles;
	sort( $roles );
	return substr( md5( implode( ',', $roles ) ), 0, 12 );
}
